	#endif
	#if NUM_HEMI_LIGHTS > 0
	irradiance += uHemiOn * ( mix( uHemiGround, uHemiSky, 0.5 * dot( geometryNormal, hemisphereLights[ 0 ].direction ) + 0.5 ) - getHemisphereLightIrradiance( hemisphereLights[ 0 ], geometryNormal ) );
