halo.vertex:
attribute vec3 aCenter;
attribute vec3 aColor;
attribute float aRadius;
varying vec2 vHalo;
varying vec3 vColor;
void main() {
  // The view matrix's rows are the camera's right / up axes in world space.
  vec3 right = vec3( viewMatrix[ 0 ][ 0 ], viewMatrix[ 1 ][ 0 ], viewMatrix[ 2 ][ 0 ] );
  vec3 up = vec3( viewMatrix[ 0 ][ 1 ], viewMatrix[ 1 ][ 1 ], viewMatrix[ 2 ][ 1 ] );
  vec3 world = aCenter + ( right * position.x + up * position.y ) * aRadius;
  vHalo = position.xy;
  vColor = aColor;
  gl_Position = projectionMatrix * viewMatrix * vec4( world, 1.0 );
}

halo.fragment:
  uniform float uGain;

uniform vec4 uCalmRects[ 4 ];
uniform float uCalmCount;
uniform vec2 uCalmViewport;
uniform float uCalmFeather;
float calmAt( vec2 fragCoord ) {
  vec2 uv = fragCoord / max( uCalmViewport, vec2( 1.0 ) );
  float calm = 0.0;
  for ( int i = 0; i < 4; i ++ ) {
    if ( float( i ) >= uCalmCount ) break;
    vec4 r = uCalmRects[ i ];
    vec2 d = max( r.xy - uv, uv - r.zw );
    float outside = max( d.x, d.y );
    calm = max( calm, 1.0 - smoothstep( 0.0, max( uCalmFeather, 1e-4 ), outside ) );
  }
  return calm;
}

  varying vec2 vHalo;
  varying vec3 vColor;
  void main() {
    float r2 = dot( vHalo, vHalo );
    float glow = exp( - r2 * 5.0 ) * 0.35 + exp( - r2 * 40.0 ) * 0.25;
    // A faint vertical rain smear below the head (static).
    float smear = exp( - vHalo.x * vHalo.x * 60.0 ) * smoothstep( - 1.0, - 0.5, vHalo.y ) * ( 1.0 - smoothstep( - 0.1, 0.2, vHalo.y ) ) * 0.06;
    float fade = 1.0 - smoothstep( 0.8, 1.0, sqrt( r2 ) );
    float a = ( glow + smear ) * fade * uGain * ( 1.0 - calmAt( gl_FragCoord.xy ) );
    gl_FragColor = vec4( vColor * a, 1.0 );
  }

contactBlobs.vertex:
attribute float aFade;
varying vec2 vUv;
varying float vFade;
void main() {
  vUv = uv * 2.0 - 1.0;
  vFade = aFade;
  gl_Position = projectionMatrix * modelViewMatrix * instanceMatrix * vec4(position, 1.0);
}

contactBlobs.fragment:
uniform vec3 uColor;
uniform float uOpacity;
varying vec2 vUv;
varying float vFade;
void main() {
  float r2 = dot(vUv, vUv);
  float a = 1.0 - min(r2, 1.0);
  // LOOK r5: a firmer core ((1 − r²)^1.5) so the figure sits on the setts.
  a = a * sqrt(a) * uOpacity * vFade;
  if (a <= 0.002) discard;
  gl_FragColor = vec4(uColor, a);
}

skyBody.vertex:
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

skyBody.fragment:
uniform vec3 uColor;
uniform float uGain;
uniform float uNight;
varying vec2 vUv;

void main() {
  vec2 d = vUv - 0.5;
  float r = length(d) * 2.0;

  if (uNight < 0.5) {
    float core = exp(-r * r * 18.0);
    float halo = exp(-r * r * 4.4);
    float a = (core * 1.15 + halo * 0.38) * uGain;
    gl_FragColor = vec4(uColor * (0.35 + a), clamp(a, 0.0, 1.0));
    return;
  }

  // Few-px hot core. Inner/halo weights stay below 1 so they cannot
  // flatten into a circular 255 plateau (r2 failure).
  float core = exp(-r * r * 720.0);
  float inner = exp(-r * r * 36.0);
  float halo = exp(-r * r * 6.4);
  float veil = exp(-r * r * 5.2);
  float a = (core * 1.35 + inner * 0.16 + halo * 0.10 + veil * 0.045) * uGain;
  vec3 col = mix(uColor, vec3(1.0), core);
  gl_FragColor = vec4(col, clamp(a, 0.0, 1.0));
}

ashlar.pars:
uniform vec3 uAshCalmMin[ 8 ];
uniform vec3 uAshCalmMax[ 8 ];
uniform float uAshCalmCount;
uniform float uAshCalmFeather;
uniform vec4 uAshCourse;
uniform vec4 uAshBay;
uniform vec4 uAshBlock;
float ashHash( vec2 p ) { return fract( sin( dot( p, vec2( 12.9898, 78.233 ) ) ) * 43758.5453 ); }
// LOOK r6: a smooth 1-D value noise (drip columns — soft, never a stucco grain).
float ashNoise1( float x, float salt ) {
	float i = floor( x );
	float f = fract( x );
	return mix( ashHash( vec2( i, salt ) ), ashHash( vec2( i + 1.0, salt ) ), f * f * ( 3.0 - 2.0 * f ) );
}
float ashCalmAt( vec3 p ) {
	float calm = 0.0;
	for ( int i = 0; i < 8; i ++ ) {
		if ( float( i ) >= uAshCalmCount ) break;
		vec3 d = max( uAshCalmMin[ i ] - p, p - uAshCalmMax[ i ] );
		float outside = max( max( d.x, d.y ), d.z );
		calm = max( calm, 1.0 - smoothstep( 0.0, max( uAshCalmFeather, 1e-3 ), outside ) );
	}
	return calm;
}

ashlar.map:
vec3 ashW = ( ( vec4( - vViewPosition, 1.0 ) - viewMatrix[ 3 ] ) * viewMatrix ).xyz;
vec3 ashN = abs( normalize( cross( dFdx( ashW ), dFdy( ashW ) ) ) );
float ashKeep = uAshBay.z * ( 1.0 - ashCalmAt( ashW ) );
float ashWall = 1.0 - step( 0.7, ashN.y );
float ashS = ashN.x > ashN.z ? ashW.z : ashW.x;
float ashAbove = step( uAshCourse.x, ashW.y );
float ashCH = mix( 0.5, uAshCourse.y, ashAbove );
float ashCy = ( ashW.y - uAshCourse.x * ashAbove ) / ashCH;
float ashRow = floor( ashCy );
float ashFy = fract( ashCy );
float ashStagger = mod( ashRow, 2.0 ) * 0.5 + ( ashHash( vec2( ashRow, 3.1 ) ) - 0.5 ) * 0.2;
float ashCx = ashS / uAshCourse.z + ashStagger;
float ashCol = floor( ashCx );
float ashFx = fract( ashCx );
vec2 ashFw = vec2( fwidth( ashS ), fwidth( ashW.y ) );
float ashDy = min( ashFy, 1.0 - ashFy ) * ashCH;
float ashDx = min( ashFx, 1.0 - ashFx ) * uAshCourse.z;
float ashJw = mix( 0.03, 0.020, ashAbove );
float ashJointH = 1.0 - smoothstep( ashJw, ashJw + ashFw.y * 1.5, ashDy );
float ashJointV = ashAbove * ( 1.0 - smoothstep( 0.020, 0.020 + ashFw.x * 1.5, ashDx ) );
float ashFade = 1.0 - smoothstep( 0.08, 0.25, max( ashFw.y / ashCH, ashFw.x / uAshCourse.z ) );
