float ashLip = smoothstep( 0.6, 0.85, ashUpN ) * step( 0.5, ashY );
vec3 ashBand = mix( vec3( 1.0 ), vec3( 0.820, 0.850, 0.920 ), ashPod )
	* ( 1.0 + ( 0.050 * ashNob + 0.030 * ashCrown + 0.140 * ashLip ) * ashFac + ashLotV );
