float ashDrip = ( 1.0 - smoothstep( 0.0, mix( 0.50, 1.50, ashColN2 ), ashBelow ) ) * ( 0.3 + 0.7 * smoothstep( 0.35, 0.8, ashColN ) ) * ashDripOn;
float ashSoot = smoothstep( ashTopY - 1.4, ashTopY - 0.05, ashY ) * step( ashY, ashTopY + 0.02 ) * ( 0.5 + 0.5 * ashColN ) * ashWall;
float ashBase = 1.0 - smoothstep( 0.0, 2.20, ashY );
ashBase *= ashBase * ( 0.7 + 0.3 * ashColN2 );
float ashWeather = clamp( ( ashDrip * 1.30 + ashSoot * 1.00 + ashBase * 1.00 + ashStreak * 5.000 ) * uAshBlock.y, 0.0, 1.0 );
// Window reveals: faces along the façade axis (jambs) and soffits inside a window rect.
float ashAlongN = mix( ashN.x, ashN.z, uAshBlock.w );
float ashBayA = mod( ashAlong - uAshBay.x + 0.5 * uAshBay.y, uAshBay.y ) - 0.5 * uAshBay.y;
float ashInWin = ( 1.0 - smoothstep( 0.62, 0.8, abs( ashBayA ) ) ) * max(
	smoothstep( 0.4, 0.55, ashY ) * ( 1.0 - smoothstep( 2.75, 2.9, ashY ) ),
	smoothstep( uAshCourse.x, uAshCourse.x + 0.15, ashY ) * ( 1.0 - smoothstep( uAshCourse.x + 1.75, uAshCourse.x + 1.9, ashY ) ) );
float ashJamb = max( smoothstep( 0.55, 0.8, ashAlongN ), smoothstep( 0.6, 0.85, - ashUpN ) ) * ashInWin * ashFac;
vec3 ashR6 = mix( vec3( 1.0 ), ashBand, ashKeep )
	* mix( vec3( 1.0 ), vec3( 0.620, 0.680, 0.800 ), ashWeather * ashKeep )
	* mix( vec3( 1.0 ), vec3( 0.720, 0.780, 0.840 ), ashJamb * ashKeep );
diffuseColor.rgb *= ashR6;

calmGlsl:
uniform vec4 uCalmRects[ 4 ];
uniform float uCalmCount;
uniform vec2 uCalmViewport;
uniform float uCalmFeather;
float calmAt( vec2 fragCoord ) {
  vec2 uv = fragCoord / max( uCalmViewport, vec2( 1.0 ) );
  float calm = 0.0;
  for ( int i = 0; i < 4; i ++ ) {
    if ( float( i ) >= uCalmCount ) break;
    vec4 r = uCalmRects[ i ];
    vec2 d = max( r.xy - uv, uv - r.zw );
    float outside = max( d.x, d.y );
    calm = max( calm, 1.0 - smoothstep( 0.0, max( uCalmFeather, 1e-4 ), outside ) );
  }
  return calm;
}
